import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

/**
 * Glassmorphism customization utilities
 * Allows users to customize color, transparency, blur, and outline for glass effects
 */

export interface GlassCustomization {
  /**
   * Background color for the glass effect (e.g., "oklch(100% 0 0 / 0.1)")
   * Default: uses CSS variable --glass-bg
   */
  color?: string;

  /**
   * Transparency/opacity for the background (0-1)
   * If provided, will override the alpha channel in color
   */
  transparency?: number;

  /**
   * Overall glass solidity (0–1). 0 = the variant's natural sheer glass (default), 1 = fully solid. Sets the
   * `--glass-opacity` floor the glass utilities read — keeps the tint / gradient / blur, just makes the
   * surface less see-through. (Unlike `transparency`, which replaces the whole background with flat white.)
   */
  opacity?: number;

  /**
   * Blur amount in pixels
   * Default: uses CSS variable --blur (20px)
   */
  blur?: number | string;

  /**
   * Border/outline color (e.g., "oklch(100% 0 0 / 0.25)")
   * Default: uses CSS variable --glass-border
   */
  outline?: string;

  /**
   * Border/outline width in pixels
   * Default: 1px
   */
  outlineWidth?: number | string;

  /**
   * Shadow for the glass effect
   * Default: uses CSS variable --glass-shadow
   */
  shadow?: string;

  /**
   * Inner glow color and intensity (e.g., "oklch(100% 0 0 / 0.2)")
   * Creates an inset shadow for a glowing effect inside the element
   */
  innerGlow?: string;

  /**
   * Inner glow blur/spread radius in pixels
   * Default: 20px
   */
  innerGlowBlur?: number | string;
}

/**
 * Set or replace the alpha channel on any CSS color string.
 * Handles oklch(), hex, and rgb/rgba formats — always outputs oklch.
 */
function setAlpha(color: string, alpha: number): string {
  // oklch(...) — replace or append alpha
  const oklchMatch = color.match(/^oklch\(([^/)]+?)(?:\s*\/\s*[\d.]+)?\)$/);
  if (oklchMatch) {
    return `oklch(${oklchMatch[1].trim()} / ${alpha})`;
  }

  // hex — convert to oklch with alpha
  if (color.startsWith("#")) {
    const hex = color.replace("#", "");
    const r = parseInt(hex.substring(0, 2), 16) / 255;
    const g = parseInt(hex.substring(2, 4), 16) / 255;
    const b = parseInt(hex.substring(4, 6), 16) / 255;
    // Approximate lightness for simple hex fallback
    const l = 0.2126 * r + 0.7152 * g + 0.0722 * b;
    return `oklch(${(l * 100).toFixed(1)}% 0 0 / ${alpha})`;
  }

  // rgb/rgba — convert to oklch with alpha
  const rgbaMatch = color.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
  if (rgbaMatch) {
    const l = (0.2126 * +rgbaMatch[1] + 0.7152 * +rgbaMatch[2] + 0.0722 * +rgbaMatch[3]) / 255;
    return `oklch(${(l * 100).toFixed(1)}% 0 0 / ${alpha})`;
  }

  // Unknown format — wrap with color-mix as fallback
  return `color-mix(in oklch, ${color} ${Math.round(alpha * 100)}%, transparent)`;
}

/**
 * Converts glass customization props to CSS style object
 */
export function getGlassStyles(customization?: GlassCustomization): React.CSSProperties {
  if (!customization) return {};

  const styles = {} as React.CSSProperties & Record<`--${string}`, string | number>;

  // Handle background color and transparency
  if (customization.color || customization.transparency !== undefined) {
    let bgColor = customization.color || "oklch(100% 0 0 / 0.1)";

    if (customization.transparency !== undefined) {
      bgColor = setAlpha(bgColor, customization.transparency);
    }

    styles.backgroundColor = bgColor;
  }

  // Overall solidity — sets the --glass-opacity floor the glass utilities lay behind the surface (0 = the
  // variant's natural sheer glass, 1 = fully solid). Keeps the tint / gradient / blur intact.
  if (customization.opacity !== undefined) {
    styles["--glass-opacity"] = customization.opacity;
  }

  // Handle blur
  if (customization.blur !== undefined) {
    const blurValue = typeof customization.blur === "number" ? `${customization.blur}px` : customization.blur;
    styles.backdropFilter = `blur(${blurValue})`;
    styles.WebkitBackdropFilter = `blur(${blurValue})`; // Safari support
  }

  // Handle outline/border - always apply border for glassmorphism effect
  if (customization.outline !== undefined) {
    const width = customization.outlineWidth || "1px";
    styles.borderColor = customization.outline;
    styles.borderWidth = typeof width === "number" ? `${width}px` : width;
    styles.borderStyle = "solid";
  } else if (!customization.outline && (customization.color || customization.transparency !== undefined || customization.blur !== undefined)) {
    // Apply default border if glass customization is provided but outline is not
    styles.borderColor = "oklch(100% 0 0 / 0.3)";
    styles.borderWidth = "1px";
    styles.borderStyle = "solid";
  }

  // Handle shadow and inner glow - combine both if provided
  const shadows: string[] = [];

  // Add outer shadow
  if (customization.shadow !== undefined) {
    shadows.push(customization.shadow);
  } else if (customization.color || customization.transparency !== undefined || customization.blur !== undefined) {
    // Apply default glass shadow for depth
    shadows.push("0 8px 32px oklch(0% 0 0 / 0.1), 0 2px 8px oklch(0% 0 0 / 0.05)");
  }

  // Add inner glow as inset shadow
  if (customization.innerGlow !== undefined) {
    const glowBlur =
      customization.innerGlowBlur !== undefined
        ? typeof customization.innerGlowBlur === "number"
          ? `${customization.innerGlowBlur}px`
          : customization.innerGlowBlur
        : "20px";
    shadows.push(`inset 0 0 ${glowBlur} ${customization.innerGlow}`);
  }

  if (shadows.length > 0) {
    styles.boxShadow = shadows.join(", ");
  }

  return styles;
}

/**
 * Generates CSS custom properties for glass customization
 * Useful for components that need to pass styles to child elements
 */
export function getGlassCSSVars(customization?: GlassCustomization): Record<string, string> {
  if (!customization) return {};

  const vars: Record<string, string> = {};

  if (customization.color || customization.transparency !== undefined) {
    let bgColor = customization.color || "oklch(100% 0 0 / 0.1)";

    if (customization.transparency !== undefined) {
      bgColor = setAlpha(bgColor, customization.transparency);
    }

    vars["--glass-bg-custom"] = bgColor;
  }

  if (customization.opacity !== undefined) {
    vars["--glass-opacity"] = String(customization.opacity);
  }

  if (customization.blur !== undefined) {
    const blurValue = typeof customization.blur === "number" ? `${customization.blur}px` : customization.blur;
    vars["--blur-custom"] = blurValue;
  }

  if (customization.outline !== undefined) {
    vars["--glass-border-custom"] = customization.outline;
  }

  if (customization.outlineWidth !== undefined) {
    const width = typeof customization.outlineWidth === "number" ? `${customization.outlineWidth}px` : customization.outlineWidth;
    vars["--glass-border-width-custom"] = width;
  }

  if (customization.shadow !== undefined) {
    vars["--glass-shadow-custom"] = customization.shadow;
  }

  if (customization.innerGlow !== undefined) {
    vars["--glass-inner-glow-custom"] = customization.innerGlow;
  }

  if (customization.innerGlowBlur !== undefined) {
    const blurValue = typeof customization.innerGlowBlur === "number" ? `${customization.innerGlowBlur}px` : customization.innerGlowBlur;
    vars["--glass-inner-glow-blur-custom"] = blurValue;
  }

  return vars;
}

import { cva } from "class-variance-authority";

/**
 * Shared hover effect variants for all Sistine components
 *
 * Effects:
 * - none: No hover effect
 * - glow: Themed glow shadow (--glass-glow, follows the tint hue) that intensifies on hover
 * - shimmer: Moving shimmer effect across the component
 * - ripple: Ripple effect that scales outward on hover
 * - lift: Subtle lift effect with shadow increase
 * - scale: Scale up slightly on hover
 */
export const hoverEffects = cva("transition duration-300", {
  variants: {
    hover: {
      none: "",
      glow: "glass-glow hover:glass-glow-lg",
      shimmer:
        "relative overflow-hidden before:absolute before:inset-0 before:-translate-x-full before:bg-gradient-to-r before:from-transparent before:via-white/20 before:to-transparent hover:before:translate-x-full before:transition-transform before:duration-1000",
      ripple:
        "relative overflow-hidden after:absolute after:inset-0 after:scale-0 after:rounded-full after:bg-white/30 after:transition-transform after:duration-500 hover:after:scale-150",
      lift: "hover:-translate-y-1 hover:shadow-lg",
      scale: "hover:scale-105",
    },
  },
  defaultVariants: {
    hover: "none",
  },
});

export type HoverEffect = "none" | "glow" | "shimmer" | "ripple" | "lift" | "scale";

"use client";

import { CaretDownIcon, CaretUpIcon, Check } from "@phosphor-icons/react";
import { cva, type VariantProps } from "class-variance-authority";
import { Select as SelectPrimitive } from "radix-ui";
import * as React from "react";

import { type GlassCustomization, getGlassStyles } from "@/lib/glass-utils";
import { cn } from "@/lib/utils";

const selectTriggerVariants = cva(
  "flex w-full items-center justify-between whitespace-nowrap rounded-md border px-3 py-2 text-sm shadow-sm ring-offset-background placeholder:text-muted-foreground focus:outline-none focus:ring-1 focus:ring-ring disabled:cursor-not-allowed disabled:opacity-50 data-[size=default]:h-9 data-[size=sm]:h-8 data-[placeholder]:text-muted-foreground [&>span]:line-clamp-1",
  {
    variants: {
      variant: {
        default: "border-input bg-background",
        glass: "glass-surface",
        frosted: "glass-frosted",
        crystal: "glass-crystal",
        opaque: "glass-opaque",
        surface: "glass-surface text-foreground",
        solid: "glass-solid text-foreground",
      },
    },
    defaultVariants: {
      variant: "glass",
    },
  },
);

const selectContentVariants = cva(
  "relative z-50 max-h-96 min-w-[8rem] overflow-hidden rounded-xl shadow-md data-[state=open]:animate-in data-[state=closed]:animate-out data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 data-[state=closed]:zoom-out-95 data-[state=open]:zoom-in-95 data-[side=bottom]:slide-in-from-top-2 data-[side=left]:slide-in-from-right-2 data-[side=right]:slide-in-from-left-2 data-[side=top]:slide-in-from-bottom-2",
  {
    variants: {
      variant: {
        default: "bg-popover text-popover-foreground border",
        glass: "glass-solid text-foreground",
        frosted: "glass-frosted text-foreground",
        crystal: "glass-crystal text-foreground",
        opaque: "glass-opaque text-foreground",
        surface: "glass-surface text-foreground",
        solid: "glass-solid text-foreground",
      },
    },
    defaultVariants: {
      variant: "glass",
    },
  },
);

const Select = SelectPrimitive.Root;

const SelectGroup = SelectPrimitive.Group;

const SelectValue = SelectPrimitive.Value;

const SelectTrigger = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Trigger>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger> &
    VariantProps<typeof selectTriggerVariants> & {
      size?: "sm" | "default";
    }
>(({ className, children, variant = "glass", size = "default", ...props }, ref) => {
  return (
    <SelectPrimitive.Trigger
      ref={ref}
      data-slot="select-trigger"
      data-size={size}
      className={cn(
        selectTriggerVariants({
          variant,
        }),
        className,
      )}
      {...props}
    >
      {children}
      <SelectPrimitive.Icon asChild>
        <CaretDownIcon className="h-4 w-4 opacity-50" />
      </SelectPrimitive.Icon>
    </SelectPrimitive.Trigger>
  );
});
SelectTrigger.displayName = SelectPrimitive.Trigger.displayName;

const SelectScrollUpButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollUpButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollUpButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollUpButton
    ref={ref}
    data-slot="select-scroll-up-button"
    className={cn("flex cursor-default items-center justify-center py-1", className)}
    {...props}
  >
    <CaretUpIcon className="h-4 w-4" />
  </SelectPrimitive.ScrollUpButton>
));
SelectScrollUpButton.displayName = SelectPrimitive.ScrollUpButton.displayName;

const SelectScrollDownButton = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.ScrollDownButton>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.ScrollDownButton>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.ScrollDownButton
    ref={ref}
    data-slot="select-scroll-down-button"
    className={cn("flex cursor-default items-center justify-center py-1", className)}
    {...props}
  >
    <CaretDownIcon className="h-4 w-4" />
  </SelectPrimitive.ScrollDownButton>
));
SelectScrollDownButton.displayName = SelectPrimitive.ScrollDownButton.displayName;

const SelectContent = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Content>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content> &
    VariantProps<typeof selectContentVariants> & {
      glass?: GlassCustomization;
    }
>(({ className, children, position = "popper", align = "center", variant = "glass", glass, style, ...props }, ref) => {
  const hasCustomGlass = glass !== undefined;
  const effectiveVariant = hasCustomGlass && variant !== "default" ? "glass" : variant;
  const glassStyles = variant !== "default" ? getGlassStyles(glass) : {};
  return (
    <SelectPrimitive.Portal>
      <SelectPrimitive.Content
        ref={ref}
        data-slot="select-content"
        className={cn(
          selectContentVariants({
            variant: effectiveVariant,
          }),
          position === "popper" &&
            "data-[side=bottom]:translate-y-1 data-[side=left]:-translate-x-1 data-[side=right]:translate-x-1 data-[side=top]:-translate-y-1",
          className,
        )}
        style={{
          ...glassStyles,
          ...style,
        }}
        position={position}
        align={align}
        {...props}
      >
        <SelectScrollUpButton />
        <SelectPrimitive.Viewport
          className={cn(
            "p-1",
            position === "popper" && "h-[var(--radix-select-trigger-height)] w-full min-w-[var(--radix-select-trigger-width)] scroll-my-1",
          )}
        >
          {children}
        </SelectPrimitive.Viewport>
        <SelectScrollDownButton />
      </SelectPrimitive.Content>
    </SelectPrimitive.Portal>
  );
});
SelectContent.displayName = SelectPrimitive.Content.displayName;

const SelectLabel = React.forwardRef<React.ElementRef<typeof SelectPrimitive.Label>, React.ComponentPropsWithoutRef<typeof SelectPrimitive.Label>>(
  ({ className, ...props }, ref) => (
    <SelectPrimitive.Label ref={ref} data-slot="select-label" className={cn("px-2 py-1.5 text-sm font-semibold", className)} {...props} />
  ),
);
SelectLabel.displayName = SelectPrimitive.Label.displayName;

const SelectItem = React.forwardRef<React.ElementRef<typeof SelectPrimitive.Item>, React.ComponentPropsWithoutRef<typeof SelectPrimitive.Item>>(
  ({ className, children, ...props }, ref) => (
    <SelectPrimitive.Item
      ref={ref}
      data-slot="select-item"
      className={cn(
        "relative flex w-full cursor-default select-none items-center rounded-sm py-1.5 pl-2 pr-8 text-sm outline-none focus:bg-foreground/10 focus:text-accent-foreground data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className,
      )}
      {...props}
    >
      <span data-slot="select-item-indicator" className="absolute right-2 flex h-3.5 w-3.5 items-center justify-center">
        <SelectPrimitive.ItemIndicator>
          <Check className="h-4 w-4" />
        </SelectPrimitive.ItemIndicator>
      </span>
      <SelectPrimitive.ItemText>{children}</SelectPrimitive.ItemText>
    </SelectPrimitive.Item>
  ),
);
SelectItem.displayName = SelectPrimitive.Item.displayName;

const SelectSeparator = React.forwardRef<
  React.ElementRef<typeof SelectPrimitive.Separator>,
  React.ComponentPropsWithoutRef<typeof SelectPrimitive.Separator>
>(({ className, ...props }, ref) => (
  <SelectPrimitive.Separator ref={ref} data-slot="select-separator" className={cn("-mx-1 my-1 h-px bg-muted", className)} {...props} />
));
SelectSeparator.displayName = SelectPrimitive.Separator.displayName;

export {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectScrollDownButton,
  SelectScrollUpButton,
  SelectSeparator,
  SelectTrigger,
  SelectValue,
};

"use client";

import type { Select as SelectPrimitive } from "radix-ui";
import * as React from "react";
import {
  Select as BaseSelect,
  SelectContent as BaseSelectContent,
  SelectTrigger as BaseSelectTrigger,
  SelectItem,
  SelectValue,
} from "@/components/ui/select";
import { cn } from "@/lib/utils";

type SelectVariant = "default" | "glass" | "frosted" | "crystal" | "opaque";

export interface SelectTriggerProps extends React.ComponentPropsWithoutRef<typeof SelectPrimitive.Trigger> {
  variant?: SelectVariant;
  glow?: boolean;
}

export interface SelectContentProps extends React.ComponentPropsWithoutRef<typeof SelectPrimitive.Content> {
  variant?: SelectVariant;
  glow?: boolean;
}

/**
 * Sistine Select - Enhanced select with glassy effects
 */
export const SelectTrigger = React.forwardRef<React.ElementRef<typeof BaseSelectTrigger>, SelectTriggerProps>(
  ({ className, variant = "glass", glow = false, ...props }, ref) => {
    return (
      <BaseSelectTrigger
        ref={ref}
        className={cn(glow && "glass-glow", "transition duration-200", className)}
        {...({
          variant,
          ...props,
        } as React.ComponentProps<typeof BaseSelectTrigger>)}
      />
    );
  },
);
SelectTrigger.displayName = "SelectTrigger";

export const SelectContent = React.forwardRef<React.ElementRef<typeof BaseSelectContent>, SelectContentProps>(
  ({ className, variant = "glass", glow = false, ...props }, ref) => {
    return (
      <BaseSelectContent
        ref={ref}
        className={cn(glow && "glass-glow", className)}
        {...({
          variant,
          ...props,
        } as React.ComponentProps<typeof BaseSelectContent>)}
      />
    );
  },
);
SelectContent.displayName = "SelectContent";

export { BaseSelect as Select, SelectItem, SelectValue };
